WorkspaceConfig = dataclass(WorkspaceConfig)
DEFAULT_WORKSPACE = WorkspaceConfig()
_MIN_CAMERA_DEPTH_M = 0.08
_MAX_CAMERA_DEPTH_M = 3
_MAX_NEAR_REPROJECTION_ERROR = 0.25
_MIN_POINT_DEPTH_M = 0.02
_RAY_ITERATIONS = 2
_fallback_logged = False
_MP_WRIST = 0
_MP_INDEX_MCP = 5
_MP_PINKY_MCP = 17

def _palm_width(image_landmarks):
    '''Apparent palm width: image-space distance between the knuckles (5, 17).

    Knuckle span is a stable scale cue — unlike a bounding box it does not change
    when the fingers curl, so it tracks distance-to-camera rather than gesture.
    '''
    if len(image_landmarks) <= _MP_PINKY_MCP:
        return 0
    (ax, ay, _) = image_landmarks[_MP_INDEX_MCP]
    (bx, by, _) = image_landmarks[_MP_PINKY_MCP]
    return math.hypot(ax - bx, ay - by)


def _estimate_depth_offset(image_landmarks, config):
    """Offset (meters) to add to ``center.z`` from the hand's apparent size.

    Negative = closer to the camera (forward, into the scene); positive = farther
    (back, toward the user). Clamped to ``±depth_range``.
    """
    size = _palm_width(image_landmarks)
    ref = config.reference_hand_size
    if size <= 1e-06 or ref <= 1e-06:
        return 0
    rel = size / ref
    offset = -(config.depth_range) * (rel - 1)
    return max(-(config.depth_range), min(config.depth_range, offset))


def estimate_stage_position(image_landmarks, config):
    '''Map image-space hand landmarks to a stage-space wrist position.

    Args:
        image_landmarks: 21 normalized image-space landmarks from MediaPipe
            hand_landmarks. The wrist (index 0) drives lateral placement; the
            knuckle span (indices 5 and 17) drives depth. Each landmark is
            (x, y, z) with x, y in [0, 1].
        config: Workspace mapping parameters. Uses DEFAULT_WORKSPACE if None.

    Returns:
        (x, y, z) position in stage space, meters.
    '''
    if config is None:
        config = DEFAULT_WORKSPACE
    wrist = image_landmarks[_MP_WRIST]
    (img_x, img_y, _img_z) = wrist
    stage_x = config.center[0] + (0.5 - img_x) * config.width
    stage_y = config.center[1] + (0.5 - img_y) * config.height
    stage_z = config.center[2] + _estimate_depth_offset(image_landmarks, config)
    return (stage_x, stage_y, stage_z)


def _solve_translation(points, image_landmarks, config):
    """Translation t (meters) that makes camera-aligned ``points + t`` project
    onto the image landmarks under the pinhole model.

    Each landmark gives two equations that are linear in t:

        xn * (Z + tz) = X + tx    and    yn * (Z + tz) = Y + ty

    with (xn, yn) the landmark's normalized camera ray. Using all 21 points
    makes depth respond to the whole hand's projected size, including its
    foreshortening, rather than one rotation-sensitive knuckle span.
    """
    count = len(points)
    image = np.asarray(image_landmarks, dtype = np.float64)
    xn = (image[:, 0] - 0.5) / config.focal_length
    yn = (image[:, 1] - 0.5) * config.image_aspect / config.focal_length
    a = np.zeros((2 * count, 3))
    b = np.empty(2 * count)
    a[:count, 0] = 1
    a[:count, 2] = -xn
    b[:count] = xn * points[:, 2] - points[:, 0]
    a[count:, 1] = 1
    a[count:, 2] = -yn
    b[count:] = yn * points[:, 2] - points[:, 1]
    translation = np.linalg.lstsq(a, b, rcond = None)[0]
    depth = points[:, 2] + translation[2]
    if np.all(np.isfinite(depth)) or np.median(depth) <= 0:
        return None
    weights = 1 / np.maximum(depth, _MIN_POINT_DEPTH_M)
    weights = np.concatenate([
        weights,
        weights])
    translation = np.linalg.lstsq(a * weights[:, None], b * weights, rcond = None)[0]
    if not np.all(np.isfinite(translation)):
        return None
    wrist = points[_MP_WRIST] + translation
    if not 0 < wrist[2] or wrist[2] <= _MAX_CAMERA_DEPTH_M:
        return None
        return None
    if wrist[2] < _MIN_CAMERA_DEPTH_M:
        camera = points + translation
        if np.any(camera[:, 2] <= 0):
            return None
        error = np.hypot(camera[:, 0] / camera[:, 2] - xn, camera[:, 1] / camera[:, 2] - yn)
        extent = max(np.ptp(xn), np.ptp(yn))
        if np.sqrt(np.mean(error ** 2)) > _MAX_NEAR_REPROJECTION_ERROR * extent:
            return None
        centroid = camera.mean(axis = 0)
        translation += centroid * ((_MIN_CAMERA_DEPTH_M - wrist[2]) / centroid[2])
    return translation


def _rotation_onto_ray(ray):
    '''Smallest rotation taking the optical axis (0, 0, 1) onto ``ray``.'''
    direction = ray / np.linalg.norm(ray)
    axis = np.array([
        -direction[1],
        direction[0],
        0])
    sin = float(np.linalg.norm(axis))
    cos = float(direction[2])
    if sin < 1e-09:
        return np.eye(3)
    cross = np.array([
        [
            0,
            -axis[2],
            axis[1]],
        [
            axis[2],
            0,
            -axis[0]],
        [
            -axis[1],
            axis[0],
            0]])
    return np.eye(3) + cross + (cross @ cross) * ((1 - cos) / (sin * sin))


def solve_camera_pose(world_landmarks, image_landmarks, config):
    """Rotation R and translation t with ``R @ world + t`` in camera space.

    MediaPipe predicts world landmarks from a crop centered on the hand, so
    their axes are aligned with that crop's viewing ray rather than with the
    camera's optical axis. Off-center hands are therefore rotated by the
    angle between the two, which compresses lateral motion and biases depth
    near the image edges. R undoes that by turning the optical axis onto the
    ray through the hand's centroid (found by alternating with the
    translation solve); unlike a free PnP rotation it has no flip ambiguity
    for flat hands.

    Returns None when the inputs are degenerate or the solution lies outside
    a plausible camera depth range.
    """
    count = len(world_landmarks)
    if count < 4 and count != len(image_landmarks) or config.focal_length <= 1e-06:
        return None
    points = np.asarray(world_landmarks, dtype = np.float64)[:, :3]
    rotation = np.eye(3)
    translation = _solve_translation(points, image_landmarks, config)
    for _ in range(_RAY_ITERATIONS):
        if translation is None:
            range(_RAY_ITERATIONS)
            return None
        centroid = (rotation @ points.mean(axis = 0)) + translation
        rotation = _rotation_onto_ray(centroid)
        translation = _solve_translation(points @ rotation.T, image_landmarks, config)
    if translation is None:
        return None
    return (rotation, translation)


def apply_reach_gain(stage_point, config):
    """Scale a stage point's lateral offset from ``reach_center`` by
    ``reach_gain``; depth is unchanged."""
    (x, y, z) = stage_point
    (gx, gy) = config.reach_gain
    (cx, cy) = config.reach_center
    return (cx + gx * (x - cx), cy + gy * (y - cy), z)


